parameters.jsCode:
const candidate = $input.item.json.candidates[0];
const contentText = candidate.content.parts[0].text;

let sources = [];
if (candidate.groundingMetadata && candidate.groundingMetadata.groundingChunks) {
  sources = candidate.groundingMetadata.groundingChunks.map(c => {
    if (c.web) return `• [${c.web.title}](${c.web.uri})`;
    return null;
  }).filter(Boolean);
}

const query = $("Execute Workflow Trigger").item.json.parameters.query || 'Executive Research';
const timestamp = new Date().toISOString().split('T')[0];
const docTitle = `Nova Research - ${query.substring(0, 40)} (${timestamp})`;

return {
  json: {
    doc_title: docTitle,
    query: query,
    research_content: contentText,
    sources_list: sources.join('\n'),
    timestamp: timestamp
  }
};

