parameters.jsCode:
const researchContent = $('Format Research Report').item.json.research_content || '';
const query = $('Format Research Report').item.json.query || '';
const docId = $('Create Google Doc Report').item.json.id || '';

let cleanText = researchContent
  .replace(/#+\s*/g, '')
  .replace(/\*+/g, '')
  .replace(/\[([^\]]+)\]\([^\)]+\)/g, '$1')
  .replace(/\n+/g, ' ')
  .trim();

if (cleanText.length > 300) {
  cleanText = cleanText.substring(0, 300) + '... Full report saved to Google Drive.';
}

return {
  json: {
    status: 'COMPLETED',
    query: query,
    doc_id: docId,
    doc_url: `https://docs.google.com/document/d/${docId}/edit`,
    message: `Here is what I found for ${query}: ${cleanText}`
  }
};
